// A token bucket. Holds `capacity` tokens, refills `refill` tokens for every
// `per` ticks that pass, and never lets its stock exceed `capacity`. Keeps
// one independent state per key, represented as an exact fraction of tokens
// with a fixed denominator of `per` so that partial refills never need to be
// rounded.
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityUnits = capacity * per
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { units: this.capacityUnits, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const gained = this.refill * elapsed
      let units = state.units + gained
      if (units > this.capacityUnits) units = this.capacityUnits
      state.units = units
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.#stateFor(key)
    return state.units >= this.per
  }

  record(key) {
    const state = this.#stateFor(key)
    state.units -= this.per
  }
}

// A sliding window. Remembers the ticks of requests it recorded for a key,
// and forgets ones that fall at or before `tick - span`. Keeps one
// independent queue of remembered ticks per key.
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const queue = this.#stateFor(key)
    const threshold = tick - this.span
    while (queue.length > 0 && queue[0] <= threshold) {
      queue.shift()
    }
  }

  allow(key) {
    const queue = this.#stateFor(key)
    return BigInt(queue.length) < this.limit
  }

  record(key) {
    const queue = this.#stateFor(key)
    // The current tick is not known here directly; record() is always
    // called immediately after allow() within the same advance, so the
    // caller passes the tick explicitly via recordAt.
    throw new Error('use recordAt')
  }

  recordAt(key, tick) {
    const queue = this.#stateFor(key)
    queue.push(tick)
  }
}
"}

