{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-qqQj5x/src/simulate.js","content":"'use strict'

import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

class ParseError extends Error {
  constructor(lineNum, reason) {
    super(`line ${lineNum}: ${reason}`)
    this.lineNum = lineNum
    this.reason = reason
  }
}

function isValidName(str) {
  return NAME_RE.test(str)
}

// Validates that `str` is a well-formed unsigned decimal integer (no sign,
// no leading zero unless the value is exactly zero) of at least `min`.
// Returns the parsed BigInt, or `null` when invalid.
function parseIntField(str, min) {
  if (!INT_RE.test(str)) return null
  const value = BigInt(str)
  if (value < min) return null
  return value
}

function splitLine(line) {
  const trimmed = line.trim()
  if (trimmed === '' || trimmed.startsWith('#')) return null
  return trimmed.split(/\s+/)
}

// Finds the route whose prefix is longest among those that match `key`, or
// `null` if none match.
function findRoute(routes, key) {
  let best = null
  let bestLen = -1
  for (const [prefix, route] of routes) {
    if (key.startsWith(prefix) && prefix.length > bestLen) {
      best = route
      bestLen = prefix.length
    }
  }
  return best
}

// Runs the whole limiter file described by `text` and returns
// `{ events: [{ tick, key, allowed, deniedBy }] }` in log order.
// Throws a ParseError (with a `.lineNum` and `.reason`) on the first
// malformed line.
export function simulate(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const policies = new Map() // name -> policy object
  const routes = new Map() // prefix -> { policyNames: [...], policies: [...] }
  let seenEvent = false
  let lastTick = null
  const events = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNum = i + 1
    const parts = splitLine(rawLines[i])
    if (parts === null) continue

