/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { simulate } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let result
  try {
    result = simulate(input)
  } catch (err) {
    if (err && typeof err.lineNum === 'number') {
      process.stderr.write(`error: line ${err.lineNum}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  const out = []
  if (mode === 'replay') {
    for (const event of result.events) {
      if (event.allowed) {
        out.push(`${event.tick} ${event.key} allow\n`)
      } else {
        out.push(`${event.tick} ${event.key} deny ${event.deniedBy}\n`)
      }
    }
  } else {
    const stats = new Map() // key -> { allowed, denied }
    let totalAllowed = 0n
    let totalDenied = 0n
    for (const event of result.events) {
      let s = stats.get(event.key)
      if (s === undefined) {
        s = { allowed: 0n, denied: 0n }
        stats.set(event.key, s)
      }
      if (event.allowed) {
        s.allowed += 1n
        totalAllowed += 1n
      } else {
        s.denied += 1n
        totalDenied += 1n
